INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'association', 'n.', '/əˌsəʊsiˈeɪʃn/', '协会;联系;关联', 'The local cooking association holds a food festival every year.', '当地烹饪协会每年都举办美食节。', 'Food and Culture', 1, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a cooking association', '美音 /əˌsoʊsiˈeɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'bun', 'n.', '/bʌn/', '圆面包;小圆甜饼', 'She enjoys eating a warm steamed bun for breakfast.', '她喜欢早餐吃一个热乎乎的馒头。', 'Food and Culture', 2, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a steamed bun', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cabbage', 'n.', '/ˈkæbɪdʒ/', '甘蓝;卷心菜;洋白菜', 'Hand-torn cabbage is a simple but tasty home dish.', '手撕包菜是一道简单却美味的家常菜。', 'Food and Culture', 3, 0, 'senior', 'wordlist', 'elective2', 'U3', 'hand-torn cabbage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cafeteria', 'n.', '/ˌkæfəˈtɪəriə/', '自助餐厅;自助食堂', 'We had a quick lunch in the school cafeteria.', '我们在学校自助餐厅匆匆吃了午饭。', 'Food and Culture', 4, 0, 'senior', 'wordlist', 'elective2', 'U3', 'the school cafeteria', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'calorie', 'n.', '/ˈkæləri/', '卡路里(热量单位)', 'Fresh vegetables are usually low in calories.', '新鲜蔬菜通常热量很低。', 'Food and Culture', 5, 0, 'senior', 'wordlist', 'elective2', 'U3', 'low in calories', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'canteen', 'n.', '/kænˈtiːn/', '食堂;餐厅', 'We just ate whatever was left in the university canteen.', '我们只吃了大学食堂里剩下的东西。', 'Food and Culture', 6, 0, 'senior', 'wordlist', 'elective2', 'U3', 'the university canteen', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'category', 'n.', '/ˈkætəɡəri/', '类别;种类', 'A balanced diet includes different categories of fresh food.', '均衡的饮食包含不同类别的新鲜食物。', 'Food and Culture', 7, 0, 'senior', 'wordlist', 'elective2', 'U3', 'different categories of food', '美音 /ˈkætəɡɔːri/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'chef', 'n.', '/ʃef/', '厨师;主厨', 'The chef began filling our table with the best food we had ever eaten.', '主厨开始把我们吃过最好的菜摆满餐桌。', 'Food and Culture', 8, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a famous chef', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'chew', 'v./n.', '/tʃuː/', '咀嚼;嚼碎', 'People who chew too quickly often end up eating too much.', '嚼得太快的人往往吃得过多。', 'Food and Culture', 9, 0, 'senior', 'wordlist', 'elective2', 'U3', 'chew slowly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'chilli', 'n.', '/ˈtʃɪli/', '辣椒', 'Steamed fish head covered with chillies is a famous Hunan dish.', '剁椒鱼头是一道有名的湖南菜。', 'Food and Culture', 10, 0, 'senior', 'wordlist', 'elective2', 'U3', 'covered with chillies', '美式拼 chili');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'consist', 'v.', '/kənˈsɪst/', '组成;构成;在于', 'A traditional Western dinner can consist of soup, a main course, and dessert.', '传统西餐可以由汤、主菜和甜点组成。', 'Food and Culture', 11, 0, 'senior', 'wordlist', 'elective2', 'U3', 'consist of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'consistent', 'adj.', '/kənˈsɪstənt/', '一致的;连续的;始终如一的', 'Consistent eating habits are better for our health.', '始终如一的饮食习惯更有益健康。', 'Food and Culture', 12, 0, 'senior', 'wordlist', 'elective2', 'U3', 'consistent eating habits', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'consume', 'v.', '/kənˈsjuːm/', '吃;喝;消耗', 'You can keep healthy by consuming different fresh foods.', '多吃不同的新鲜食物有助于保持健康。', 'Food and Culture', 13, 0, 'senior', 'wordlist', 'elective2', 'U3', 'consume fresh food', '美音 /kənˈsuːm/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'cuisine', 'n.', '/kwɪˈziːn/', '菜肴;风味;烹饪', 'Chinese cuisine is famous all over the world.', '中国菜肴闻名于世。', 'Food and Culture', 14, 0, 'senior', 'wordlist', 'elective2', 'U3', 'Chinese cuisine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dairy', 'n./adj.', '/ˈdeəri/', '乳制品;乳品的', 'Dairy products provide the protein we need for strong bones.', '乳制品提供我们强健骨骼所需的蛋白质。', 'Food and Culture', 15, 0, 'senior', 'wordlist', 'elective2', 'U3', 'dairy products', '美音 /ˈderi/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dessert', 'n.', '/dɪˈzɜːt/', '(饭后)甜点', 'If you want to be healthy, you have to cut down on desserts.', '想要健康,你得少吃甜点。', 'Food and Culture', 16, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a sweet dessert', '美音 /dɪˈzɜːrt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'dough', 'n.', '/dəʊ/', '生面团', 'The chef rolled the dough thin before making the buns.', '厨师把面团擀薄,然后做包子。', 'Food and Culture', 17, 0, 'senior', 'wordlist', 'elective2', 'U3', 'roll the dough', '美音 /doʊ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'elegant', 'adj.', '/ˈelɪɡənt/', '精美的;讲究的;文雅的', 'Guangdong is known for its elegant dim sum.', '广东以其精美的点心而著称。', 'Food and Culture', 18, 0, 'senior', 'wordlist', 'elective2', 'U3', 'elegant dim sum', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'exceptional', 'adj.', '/ɪkˈsepʃənl/', '特别的;罕见的;杰出的', 'The stewed noodles in Henan have an exceptional flavour.', '河南的烩面有着特别的风味。', 'Food and Culture', 19, 0, 'senior', 'wordlist', 'elective2', 'U3', 'exceptional flavour', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'fibre', 'n.', '/ˈfaɪbə(r)/', '纤维;纤维制品', 'Fruit and vegetables are full of vitamins and fibre.', '水果和蔬菜富含维生素和纤维。', 'Food and Culture', 20, 0, 'senior', 'wordlist', 'elective2', 'U3', 'rich in fibre', '美式拼 fiber');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'fundamental', 'adj./n.', '/ˌfʌndəˈmentl/', '根本的;基础的;基本规律', 'A fundamental key to healthy eating is to eat slowly.', '健康饮食的一个根本要点是吃得慢一些。', 'Food and Culture', 21, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a fundamental key', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'garlic', 'n.', '/ˈɡɑːlɪk/', '蒜', 'He added some garlic to make the dish more tasty.', '他加了些蒜,让这道菜更香。', 'Food and Culture', 22, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a clove of garlic', '美音 /ˈɡɑːrlɪk/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ham', 'n.', '/hæm/', '火腿', 'She put a slice of ham between two buns.', '她在两块小面包之间夹了一片火腿。', 'Food and Culture', 23, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a slice of ham', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ideal', 'adj./n.', '/aɪˈdiːəl/', '理想的;完美的;理想', 'The ideal diet is a balanced one, without too much of any one thing.', '理想的饮食是均衡的,任何一样都不过量。', 'Food and Culture', 24, 0, 'senior', 'wordlist', 'elective2', 'U3', 'an ideal diet', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'ingredient', 'n.', '/ɪnˈɡriːdiənt/', '(尤指烹饪)材料;成分', 'Italy and Greece are famous for olives, figs, and other ingredients.', '意大利和希腊以橄榄、无花果等食材而闻名。', 'Food and Culture', 25, 0, 'senior', 'wordlist', 'elective2', 'U3', 'fresh ingredients', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'junk', 'n.', '/dʒʌŋk/', '垃圾;无用的东西', 'Eating too much junk food is bad for your health.', '吃太多垃圾食品对健康有害。', 'Food and Culture', 26, 0, 'senior', 'wordlist', 'elective2', 'U3', 'junk food', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'lamb', 'n.', '/læm/', '羊羔肉;羔羊', 'Their traditional food is roasted meat, such as lamb kebab.', '他们的传统食物是烤肉,比如烤羊肉串。', 'Food and Culture', 27, 0, 'senior', 'wordlist', 'elective2', 'U3', 'lamb kebab', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'madam', 'n.', '/ˈmædəm/', '夫人;女士', 'Are you ready to order, madam? asked the polite waiter.', '礼貌的服务员问道:女士,您准备好点菜了吗?', 'Food and Culture', 28, 0, 'senior', 'wordlist', 'elective2', 'U3', 'Are you ready to order, madam?', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'minimum', 'n./adj.', '/ˈmɪnɪməm/', '最小值;最少量;最低的', 'She keeps her consumption of sweets down to a minimum.', '她把甜食的摄入降到了最低限度。', 'Food and Culture', 29, 0, 'senior', 'wordlist', 'elective2', 'U3', 'to a minimum', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'moderation', 'n.', '/ˌmɒdəˈreɪʃn/', '适度;合理;节制', 'As with everything in life, moderation is key to healthy eating.', '正如生活中的一切,适度是健康饮食的关键。', 'Food and Culture', 30, 0, 'senior', 'wordlist', 'elective2', 'U3', 'in moderation', '美音 /ˌmɑːdəˈreɪʃn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'modest', 'adj.', '/ˈmɒdɪst/', '些许的;谦虚的;朴素的', 'It is better to eat a modest amount of food at each meal.', '每餐吃适量的食物会更好。', 'Food and Culture', 31, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a modest amount', '美音 /ˈmɑːdɪst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'olive', 'n.', '/ˈɒlɪv/', '油橄榄;橄榄树', 'People in Greece often cook their food with olive oil.', '希腊人常用橄榄油来烹饪食物。', 'Food and Culture', 32, 0, 'senior', 'wordlist', 'elective2', 'U3', 'olive oil', '美音 /ˈɑːlɪv/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'onion', 'n.', '/ˈʌnjən/', '洋葱;葱头', 'The pancake rolls were stuffed with sliced green onions.', '煎饼卷里塞满了切好的大葱。', 'Food and Culture', 33, 0, 'senior', 'wordlist', 'elective2', 'U3', 'green onions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'overall', 'adv./adj.', '/ˌəʊvərˈɔːl/', '总体上;全面的;综合的', 'Overall, I think I have fairly healthy eating habits.', '总体上,我觉得自己的饮食习惯还算健康。', 'Food and Culture', 34, 0, 'senior', 'wordlist', 'elective2', 'U3', 'overall, I think', '美音 /ˌoʊvərˈɔːl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pepper', 'n.', '/ˈpepə(r)/', '甜椒;灯笼椒;胡椒粉', 'The chicken was flavoured with hot red peppers.', '这道鸡肉用辣红椒调了味。', 'Food and Culture', 35, 0, 'senior', 'wordlist', 'elective2', 'U3', 'hot red peppers', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'peppercorn', 'n.', '/ˈpepəkɔːn/', '胡椒粒', 'We had the pleasure of tasting Sichuan peppercorns for the first time.', '我们有幸第一次品尝了四川花椒。', 'Food and Culture', 36, 0, 'senior', 'wordlist', 'elective2', 'U3', 'Sichuan peppercorns', '美音 /ˈpepərkɔːrn/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'pork', 'n.', '/pɔːk/', '猪肉', 'Red braised pork is one of the most famous Chinese dishes.', '红烧肉是最有名的中国菜之一。', 'Food and Culture', 37, 0, 'senior', 'wordlist', 'elective2', 'U3', 'red braised pork', '美音 /pɔːrk/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'prior', 'adj.', '/ˈpraɪə(r)/', '先前的;优先的', 'Prior to coming to China, I had only tried Chinese food in America.', '来中国之前,我只在美国吃过中餐。', 'Food and Culture', 38, 0, 'senior', 'wordlist', 'elective2', 'U3', 'prior to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'quantity', 'n.', '/ˈkwɒntəti/', '数量;数额', 'Processed foods often have higher quantities of sugar and salt.', '加工食品往往含有更高数量的糖和盐。', 'Food and Culture', 39, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a large quantity', '美音 /ˈkwɑːntəti/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'recipe', 'n.', '/ˈresəpi/', '烹饪法;食谱', 'This is probably not an authentic Chinese recipe.', '这大概并不是一道地道的中国菜谱。', 'Food and Culture', 40, 0, 'senior', 'wordlist', 'elective2', 'U3', 'an authentic recipe', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'regardless', 'adv.', '/rɪˈɡɑːdləs/', '不顾;不管;不加理会', 'Sugar harms health regardless of how healthy the rest of your diet is.', '无论你饮食的其余部分多健康,糖都会损害健康。', 'Food and Culture', 41, 0, 'senior', 'wordlist', 'elective2', 'U3', 'regardless of', '美音 /rɪˈɡɑːrdləs/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'sausage', 'n.', '/ˈsɒsɪdʒ/', '香肠;腊肠', 'She sliced off a piece of sausage for her dinner.', '她切下一块香肠作为晚餐。', 'Food and Culture', 42, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a piece of sausage', '美音 /ˈsɔːsɪdʒ/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'slice', 'n./v.', '/slaɪs/', '薄片;把……切成薄片', 'He sliced the green onions before adding them to the dish.', '他把大葱切成片,然后加进菜里。', 'Food and Culture', 43, 0, 'senior', 'wordlist', 'elective2', 'U3', 'slice off', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'somewhat', 'adv.', '/ˈsʌmwɒt/', '有点;稍微', 'Hunan cuisine is somewhat different from Sichuan cuisine.', '湖南菜与四川菜略有不同。', 'Food and Culture', 44, 0, 'senior', 'wordlist', 'elective2', 'U3', 'somewhat different', '美音 /ˈsʌmwʌt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'stable', 'adj.', '/ˈsteɪbl/', '稳定的;稳重的', 'As the person to bring home the bacon, he needs a stable job.', '作为养家糊口的人,他需要一份稳定的工作。', 'Food and Culture', 45, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a stable job', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'temper', 'n.', '/ˈtempə(r)/', '脾气;火气', 'Do those who like spicy food tend to have a hot temper?', '喜欢吃辣的人是不是更容易脾气暴躁?', 'Food and Culture', 46, 0, 'senior', 'wordlist', 'elective2', 'U3', 'a hot temper', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'trick', 'n.', '/trɪk/', '诀窍;计谋;把戏', 'There is no one trick to healthy eating.', '健康饮食没有什么单一的诀窍。', 'Food and Culture', 47, 0, 'senior', 'wordlist', 'elective2', 'U3', 'no one trick', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vegetarian', 'n./adj.', '/ˌvedʒəˈteəriən/', '素食者;素食的', 'A vegetarian eats no meat and prefers vegetables and beans.', '素食者不吃肉,更喜欢蔬菜和豆类。', 'Food and Culture', 48, 0, 'senior', 'wordlist', 'elective2', 'U3', 'vegetarian food', '美音 /ˌvedʒəˈteriən/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vinegar', 'n.', '/ˈvɪnɪɡə(r)/', '醋', 'My favourite dish was boiled dumplings served with vinegar.', '我最爱的菜是蘸醋吃的水煮饺子。', 'Food and Culture', 49, 0, 'senior', 'wordlist', 'elective2', 'U3', 'served with vinegar', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (11, 'vitamin', 'n.', '/ˈvɪtəmɪn/', '维生素', 'Fresh fruit is full of vitamins and good for you.', '新鲜水果富含维生素,对你有益。', 'Food and Culture', 50, 0, 'senior', 'wordlist', 'elective2', 'U3', 'full of vitamins', '美音 /ˈvaɪtəmɪn/');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u3.01', '①动名词作主语 / 宾语 / 表语', 'A2', 11, '选择性必修二 U3 — 动名词(doing)可作主语(Cooking is an art,作主语时谓语用单数)、作动词或介词的宾语(enjoy tasting / good at cooking)、作表语(Her hobby is baking)。', 1, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u3.02', '②现在分词作定语 / 状语', 'A2', 11, '选择性必修二 U3 — 现在分词(doing)表主动或正在进行:作定语修饰名词(the boiling water = 正在沸腾的水)、作状语表伴随/时间/原因(Smiling, she served the soup. / Tasting the dish, he nodded.)。', 2, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e2u3.03', '③-ing 作宾语补足语,及与不定式对照', 'A2', 11, '选择性必修二 U3 — 感官动词(see/hear/watch/find)及 keep/leave + sb + doing 表''正在进行'';并区分 stop/remember/try 等后接 to do(将要做)与 doing(做某事/做过)的不同含义。', 3, 'elective2', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ Chinese dishes at home is a great way to relax after school."', 'Cooking', 'Cook', 'To cook', 'Cooked', 'A', '句首作主语应用动名词 Cooking,谓语 is 单数。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"My grandma enjoys ____ dumplings with the whole family on holidays."', 'make', 'making', 'to make', 'made', 'B', 'enjoy 后接动名词 making。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"Her favourite hobby is ____ desserts for her friends at weekends."', 'bake', 'to bake', 'baking', 'baked', 'C', '表语位置用动名词 baking 说明 hobby 的内容。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ spicy food too often may not be good for your stomach."', 'Eat', 'To be eaten', 'Eaten', 'Eating', 'D', '句首作主语用动名词 Eating。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"The chef is good at ____ noodles into very thin, even strands."', 'pulling', 'pull', 'to pull', 'pulled', 'A', 'be good at 后接动名词 pulling。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"I really love ____ new dishes whenever I travel to a new city."', 'taste', 'tasting', 'to be tasted', 'tasted', 'B', 'love 后用动名词 tasting,表示一贯爱好。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ vegetables slowly helps your body take in more of the vitamins."', 'Chew', 'To be chewing', 'Chewing', 'Chewed', 'C', '句首主语用动名词 Chewing,谓语 helps 单数。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"One good way of staying healthy is ____ down on sweet drinks."', 'cut', 'to be cut', 'cuts', 'cutting', 'D', '表语位置用动名词 cutting 与主语 way 对应。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"He kept his weight down by ____ a modest amount of food each meal."', 'eating', 'eat', 'to eat', 'eaten', 'A', '介词 by 后接动名词 eating。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ different categories of fresh food keeps our diet balanced."', 'Consume', 'Consuming', 'To be consumed', 'Consumed', 'B', '句首作主语用动名词 Consuming,谓语 keeps 单数。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"My brother is afraid of ____ too many calories from junk food."', 'take in', 'to take in', 'taking in', 'taken in', 'C', '介词 of 后接动名词 taking in。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"What she likes most about cooking is ____ the fresh ingredients herself."', 'choose', 'to be chosen', 'chose', 'choosing', 'D', '表语位置用动名词 choosing,与主语对应。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ a balanced diet matters more than counting every single calorie."', 'Keeping', 'Keep', 'To be kept', 'Kept', 'A', '句首作主语用动名词 Keeping,谓语 matters 单数。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"The whole family insisted on ____ the dumplings together on New Year''s Eve."', 'wrap', 'wrapping', 'to wrap', 'wrapped', 'B', 'insist on 后接动名词 wrapping。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"Her dream is ____ a small restaurant that serves authentic Sichuan food."', 'open', 'to be opened', 'opening', 'opened', 'C', '表语位置用动名词 opening 说明 dream 的内容。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ slowly allows your brain to tell your body when you are full."', 'Eat', 'To be eaten', 'Eaten', 'Eating', 'D', '句首作主语用动名词 Eating,谓语 allows 单数。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"Many vegetarians are fond of ____ beans and tofu instead of meat."', 'eating', 'eat', 'to eat', 'eaten', 'A', 'be fond of 后接动名词 eating。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"____ healthy habits when young can protect you for the rest of your life."', 'Form', 'Forming', 'To be formed', 'Formed', 'B', '句首作主语用动名词 Forming,谓语 can 对应。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"The secret of his soup is ____ the bones for several hours over low heat."', 'boil', 'to be boiled', 'boiling', 'boiled', 'C', '表语位置用动名词 boiling 说明 secret 的内容。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.01'), '"She thanked the chef for ____ her how to make the famous red braised pork."', 'teach', 'to teach', 'taught', 'teaching', 'D', '介词 for 后接动名词 teaching。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"Be careful with the ____ water; it can burn your hand at once."', 'boiling', 'boiled', 'to boil', 'boil', 'A', '现在分词 boiling 作定语,表''正在沸腾的''(主动/进行)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____, the waiter brought us a pot of hot soup and a warm smile."', 'Smiled', 'Smiling', 'To smile', 'Smile', 'B', '现在分词 Smiling 作伴随状语,表主动同时进行。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ the strange new dish carefully, he finally nodded with delight."', 'Tasted', 'To be tasted', 'Tasting', 'Taste', 'C', '现在分词 Tasting 作状语,与主语 he 主动关系。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"The girl ____ at the next table is enjoying a bowl of beef noodles."', 'sat', 'to sit', 'sit', 'sitting', 'D', '现在分词 sitting 作定语,表''正坐着的''。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"We could smell the bread ____ in the oven as we walked past the shop."', 'baking', 'baked', 'to bake', 'bake', 'A', '现在分词 baking 作定语,表''正在烤的''。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ that the soup was too salty, the chef quickly added more water."', 'Realised', 'Realising', 'To realise', 'Realise', 'B', '现在分词 Realising 作原因状语,与主语主动。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"There is a long line of people ____ for the famous dumplings outside."', 'waited', 'to be waited', 'waiting', 'wait', 'C', '现在分词 waiting 作定语,表''正在等候的''。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ in a bamboo steamer, the dim sum looked small and elegant."', 'Sat', 'To sit', 'Sit', 'Sitting', 'D', '现在分词 Sitting 作状语,与主语 dim sum 主动关系。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"The chef stood by the fire, ____ the lamb kebab until it turned golden."', 'roasting', 'roasted', 'to roast', 'roast', 'A', '现在分词 roasting 作伴随状语,表主动进行。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"Look at the steam ____ from the bowl of freshly cooked rice!"', 'risen', 'rising', 'to rise', 'rise', 'B', '现在分词 rising 作定语,表''正在升起的''。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ hungry and tired, we were glad to find a small noodle shop."', 'Felt', 'To feel', 'Feeling', 'Feel', 'C', '现在分词 Feeling 作状语,与主语 we 主动。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"The waiter showed us a menu ____ both Chinese and English names."', 'listed', 'to list', 'list', 'listing', 'D', '现在分词 listing 作定语,表''列出……的''(主动)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ the recipe step by step, she made the dish on her first try."', 'Following', 'Followed', 'To follow', 'Follow', 'A', '现在分词 Following 作状语,与主语主动。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"The customers ____ at the round table ordered three Hunan dishes."', 'sat', 'sitting', 'to sit', 'sit', 'B', '现在分词 sitting 作定语,表''正坐着的''。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ the spicy fish head, the foreign guest asked for the recipe at once."', 'Loved', 'To love', 'Loving', 'Love', 'C', '现在分词 Loving 作原因状语,与主语主动。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"A pot of soup ____ slowly on the stove filled the kitchen with a nice smell."', 'cooked', 'to cook', 'cook', 'cooking', 'D', '现在分词 cooking 作定语,表''正在炖煮的''。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ at the busy cafeteria, the students chose their lunch quickly."', 'Arriving', 'Arrived', 'To arrive', 'Arrive', 'A', '现在分词 Arriving 作时间状语,与主语主动。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"He pointed at the chef ____ the dough high into the air."', 'tossed', 'tossing', 'to toss', 'toss', 'B', '现在分词 tossing 作定语,表''正在抛甩的''(主动)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"____ that family meant so much there, I joined them in making dumplings."', 'Known', 'To know', 'Knowing', 'Know', 'C', '现在分词 Knowing 作原因状语,与主语主动。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.02'), '"The dish ____ with hot red peppers became the most popular one."', 'covering', 'to cover', 'cover', 'covered', 'D', '菜''被''辣椒覆盖,主语与 cover 是被动关系,用过去分词 covered;此处考查 -ing 与 -ed 的对照,过去分词表被动。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"From the door I saw the chef ____ a huge pot of soup over the fire."', 'stirring', 'stir', 'to stir', 'stirred', 'A', 'see sb doing 表''看到正在做'',强调动作进行,用 stirring。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"I''m sorry to keep you ____ — the dumplings will be ready in a minute."', 'wait', 'waiting', 'to wait', 'waited', 'B', 'keep sb doing 表让某人一直处于某状态,用 waiting。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"We could hear the oil ____ in the wok before the vegetables went in."', 'hiss', 'to hiss', 'hissing', 'hissed', 'C', 'hear sth doing 表''听到正在……'',用 hissing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"She left the soup ____ on low heat while she sliced the green onions."', 'simmer', 'to simmer', 'simmered', 'simmering', 'D', 'leave sth doing 表让某物持续某动作,用 simmering。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"When I walked in, I found my mother ____ the dough for tomorrow''s buns."', 'kneading', 'knead', 'to knead', 'kneaded', 'A', 'find sb doing 表''发现某人正在做'',用 kneading。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"We watched the noodle master ____ one piece of dough into many strands."', 'pull', 'pulling', 'to pull', 'pulled', 'B', 'watch sb doing 强调动作的进行过程,用 pulling。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"On a winter day, nothing beats sitting by the fire and ____ hot soup."', 'drink', 'to drink', 'drinking', 'drunk', 'C', '与前面 sitting 并列,介词结构后用动名词 drinking。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"Remember ____ the rice before you start, or there will be nothing to cook."', 'washing', 'washed', 'wash', 'to wash', 'D', 'remember to do 表''记得去做(还没做)'';洗米在做菜前,用 to wash。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"I still remember ____ that wonderful Sichuan meal for the very first time."', 'tasting', 'to taste', 'taste', 'tasted', 'A', 'remember doing 表''记得做过(已发生)'';第一次品尝已是过去,用 tasting。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"After two hours of cooking, the tired chef stopped ____ a short rest."', 'taking', 'to take', 'took', 'take', 'B', 'stop to do 表''停下来去做另一件事'';停下做菜去休息,用 to take。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"If the soup is too salty, you should stop ____ so much salt next time."', 'to add', 'add', 'adding', 'added', 'C', 'stop doing 表''停止正在做的事'';不再放盐,用 adding。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"The recipe looked hard, but he tried ____ the dish exactly as it said."', 'making', 'made', 'make', 'to make', 'D', 'try to do 表''努力尝试去做'';他努力照食谱做,用 to make。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"The soup tasted flat, so she tried ____ a little vinegar to it."', 'adding', 'to add', 'add', 'added', 'A', 'try doing 表''试着用某法看效果'';试着加点醋,用 adding。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"I noticed several customers ____ photos of the elegant dim sum."', 'take', 'taking', 'to take', 'taken', 'B', 'notice sb doing 表''注意到正在做'',用 taking。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"The smell of garlic kept the whole family ____ around the kitchen."', 'gather', 'to gather', 'gathering', 'gathered', 'C', 'keep sb doing 表让某人持续某动作,用 gathering。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"She felt her mouth ____ the moment she smelled the spicy fish head."', 'water', 'to water', 'watered', 'watering', 'D', 'feel sth doing 表''感到正在……'',用 watering。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"Please don''t forget ____ the gas after the soup is ready."', 'to turn off', 'turning off', 'turned off', 'turn off', 'A', 'forget to do 表''忘记去做(尚未做)'';关火尚未做,用 to turn off。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"I''ll never forget ____ dumplings with my grandma when I was a child."', 'to make', 'making', 'made', 'make', 'B', 'forget doing 表''忘记做过的事'';童年包饺子已发生,用 making。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"We observed the local people ____ their bread over an open fire."', 'roast', 'to roast', 'roasting', 'roasted', 'C', 'observe sb doing 表''观察到正在做'',用 roasting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective2' AND unit='U3' AND code='e2u3.03'), '"The waiter caught a child ____ to reach the dishes on the high shelf."', 'try', 'to try', 'tried', 'trying', 'D', 'catch sb doing 表''撞见某人正在做'',用 trying。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'You Are What You Eat', 'A French writer once said, "Tell me what you eat, and I will tell you what you are." Many people today link this saying to healthy eating, but the writer was really talking about our character and culture. In many ways this seems to be true. The food that local people choose to eat tells us what grows in their region, what kind of lives they lead, and what they like or do not like. For example, those who love bold, simple flavours may also be bold in life. People who are not afraid to try strange new dishes may be open to new ideas as well. Of course, we cannot say that everyone who likes spicy food has a hot temper. Still, one thing seems clear: culture and cuisine go hand in hand. If you never experience the food of a place, you can never really know its people. Tasting a country''s dishes is a quiet way of meeting its culture face to face.', '说明·饮食与文化', 165, '[{"q":"What was the French writer mainly talking about?","answer":"A","options":["A person''s character and culture.","How to lose weight quickly.","The price of food in France.","The danger of eating too much."],"explanation":"原文 ''really talking about our character and culture'' 的转述。"},{"q":"According to the text, what can a region''s food tell us?","answer":"B","options":["The exact age of the cooks.","What grows there and how people live.","How many people live there.","Which language the people speak."],"explanation":"原文 ''what grows in their region, what kind of lives they lead'' 的概括。"},{"q":"What does the writer conclude about culture and cuisine?","answer":"A","options":["They are closely connected.","They have nothing to do with each other.","Cuisine is more important than culture.","Only spicy food shows real culture."],"explanation":"末段 ''culture and cuisine go hand in hand'' 的转述。"}]'::jsonb, '[{"word":"cuisine","cn":"菜肴;烹饪"},{"word":"flavour","cn":"风味;味道"},{"word":"temper","cn":"脾气"},{"word":"bold","cn":"大胆的"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'The Eight Great Cuisines', 'China is a huge country, and its food changes greatly from place to place. People often speak of the eight great cuisines, each with its own character. In the southwest, Sichuan cooking is famous for bold and spicy flavours, made special by the Sichuan peppercorn that leaves a tingling feeling on the tongue. Cantonese food from the south is lighter and fresher, and its elegant dim sum is served in small bamboo steamers. In the east, Shandong dishes are often boiled or steamed, and a favourite is dumplings eaten with vinegar. Each region cooks with what it can grow nearby, so the food reflects the land itself. People who live near the sea use plenty of fish, while those on the open grasslands roast meat over a fire. Wherever you travel, however, one thing stays the same: through food, Chinese people everywhere show friendship and kindness to guests. A shared meal is rarely just about eating.', '说明·八大菜系', 156, '[{"q":"What makes Sichuan cooking special, according to the text?","answer":"B","options":["Its very sweet desserts.","Its tingling, spicy peppercorn flavour.","Its use of fresh fish only.","Its lack of any seasoning."],"explanation":"原文 ''bold and spicy flavours, made special by the Sichuan peppercorn that leaves a tingling feeling'' 的转述。"},{"q":"Why does food differ so much across China?","answer":"C","options":["Because only the south has good cooks.","Because people copy foreign recipes.","Because every area uses whatever it can grow locally.","Because the weather is the same everywhere."],"explanation":"原文 ''each region cooks with what it can grow nearby'' 的转述。"},{"q":"What stays the same wherever you travel in China?","answer":"D","options":["The same single dish is served.","All food is boiled the same way.","Everyone eats only dumplings.","Food is used to show friendship and kindness."],"explanation":"末段 ''through food, Chinese people everywhere show friendship and kindness'' 的转述。"}]'::jsonb, '[{"word":"cuisine","cn":"菜系"},{"word":"peppercorn","cn":"胡椒粒;花椒"},{"word":"dim sum","cn":"点心"},{"word":"vinegar","cn":"醋"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Is Sugar the Real Enemy?', 'For years, scientists warned us that fatty food was the big enemy of good health. Today, however, more and more evidence points to a different villain: sugar. Heart disease is one of the leading killers in many countries, and studies show that people who get a quarter of their daily calories from sugar are far more likely to suffer from it. This stays true no matter how healthy the rest of their diet may be. Much of this extra sugar hides in sweet drinks; in fact, a single can of soda may hold more sugar than a person should have in a whole day. So if you want to stay well, the advice is simple. Cut down on desserts, and cut out sweet drinks altogether. Fill your plate instead with fresh fruit and vegetables, which are full of vitamins and fibre. As with everything in life, moderation is the key. The healthiest diet is a balanced one, with not too much or too little of any single thing.', '说明·食物与健康', 168, '[{"q":"What does recent evidence suggest is a major enemy of health?","answer":"A","options":["Sugar.","Fresh vegetables.","Drinking water.","Eating slowly."],"explanation":"原文 ''a different villain: sugar'' 的转述。"},{"q":"Where does much of the extra sugar come from?","answer":"B","options":["From fresh fruit.","From sweet drinks.","From plain rice.","From green vegetables."],"explanation":"原文 ''Much of this extra sugar hides in sweet drinks'' 的转述。"},{"q":"What is the writer''s main advice for a healthy diet?","answer":"C","options":["Eat as much fatty food as you like.","Drink one can of soda every meal.","Keep everything balanced and in moderation.","Never eat any fruit at all."],"explanation":"末段 ''moderation is the key… a balanced one'' 的转述。"}]'::jsonb, '[{"word":"calorie","cn":"卡路里"},{"word":"dessert","cn":"甜点"},{"word":"fibre","cn":"纤维"},{"word":"moderation","cn":"适度"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'Flavours from Around the World', 'Every country has dishes that tell its own story. Around the Mediterranean Sea, the people of Italy, Greece, and Spain cook with olives, figs, and fresh ingredients that have shaped their food for centuries. A traditional Western dinner may consist of an appetiser, a main course, soup, and a sweet dessert at the end. In Scotland, brave eaters enjoy a dish made from sheep parts, while in many parts of Asia people happily eat foods that visitors might find strange. Recently, some people have even begun to try insects, which are high in protein and far cheaper than beef. To one person a food may seem normal, yet to another the very same dish feels shocking. What counts as ''strange'' really depends on where you grew up and what you are used to. By keeping an open mind and a willing tongue, a traveller can discover that the world''s kitchens hold endless surprises, and that almost every food makes sense to someone, somewhere.', '说明·世界美食', 163, '[{"q":"What do Mediterranean countries cook with, according to the text?","answer":"D","options":["Only meat and milk.","Mainly sweet drinks.","Nothing but insects.","Olives, figs, and other fresh ingredients."],"explanation":"原文 ''cook with olives, figs, and fresh ingredients'' 的转述。"},{"q":"Why have some people started eating insects?","answer":"A","options":["Because they are rich in protein and cost less than beef.","Because they taste like dessert.","Because there is no other food.","Because doctors forbid all meat."],"explanation":"原文 ''high in protein and far cheaper than beef'' 的转述。"},{"q":"What decides whether a food seems ''strange''?","answer":"B","options":["The exact price of the dish.","Your background and the foods you are familiar with.","How large the plate is.","Whether it is served hot or cold."],"explanation":"原文 ''depends on where you grew up and what you are used to'' 的转述。"}]'::jsonb, '[{"word":"olive","cn":"橄榄"},{"word":"ingredient","cn":"食材"},{"word":"consist","cn":"组成"},{"word":"dessert","cn":"甜点"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'The Secret of Eating Slowly', 'Have you ever finished a big meal and still felt hungry a few minutes later? Scientists have an interesting answer. It takes about twenty minutes from the time you start eating for your brain to tell your body that you are full. This means that people who chew their food too quickly often end up eating far more than they need, because the signal simply has not arrived yet. Eating slowly, on the other hand, gives your body the time to send that message, and it also helps you digest your food better and enjoy it more. Studies show another helpful habit: keeping consistent meal times, for example having three meals a day at roughly the same hours. It is also wiser to eat a modest amount each time than to eat a huge meal and then almost nothing at the next. In the end, healthy eating is less about one clever trick and more about a calm, steady attitude towards every meal.', '说明·饮食习惯', 163, '[{"q":"Why do fast eaters often eat too much?","answer":"C","options":["Because their food is too sweet.","Because they never feel hungry.","Because the ''full'' signal has not reached the brain yet.","Because they dislike the food."],"explanation":"原文 ''…the signal simply has not arrived yet'' 的转述。"},{"q":"What is one benefit of eating slowly mentioned in the text?","answer":"D","options":["It makes food cost less.","It removes all sugar from food.","It lets you skip meals.","It helps you digest and enjoy your food."],"explanation":"原文 ''helps you digest your food better and enjoy it more'' 的转述。"},{"q":"What does the writer say healthy eating mainly depends on?","answer":"A","options":["A calm, steady attitude toward meals.","One single clever trick.","Eating one huge meal a day.","Counting every grain of rice."],"explanation":"末句 ''less about one clever trick and more about a calm, steady attitude'' 的转述。"}]'::jsonb, '[{"word":"chew","cn":"咀嚼"},{"word":"consistent","cn":"一致的;连续的"},{"word":"modest","cn":"些许的;适度的"},{"word":"trick","cn":"诀窍"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (11, 'A Meal Full of Kindness', 'When my family first arrived in Beijing, we were tired, hungry, and could not speak a word of Chinese. A friend had told us about a small Sichuan restaurant, and at last we found it down a narrow street. We had no idea how to read the menu or order, so we simply sat there feeling lost. Seeing this, the chef smiled and made the choice for us. He began filling our table with the best food we had ever tasted, dish after warm dish. For the first time we met the famous Sichuan peppercorn, which left a strange, exciting tingle on our tongues. Later we moved to Shandong, where my favourite meal became boiled dumplings dipped in vinegar. There I learned that making dumplings is a family affair, with everyone from the youngest child to the oldest grandparent joining in. The food was wonderful, but what stayed with me longest was something else: the warmth and friendship that were offered to a group of complete strangers.', '记叙·食物里的人情', 167, '[{"q":"Why did the chef choose the dishes for the family?","answer":"B","options":["Because the family had no money.","Because they could not understand the menu well enough to order.","Because the restaurant had only one dish.","Because the friend told him to."],"explanation":"原文 ''no idea how to read the menu or order… the chef… made the choice for us'' 的转述。"},{"q":"What did the writer learn about making dumplings in Shandong?","answer":"C","options":["It is something only chefs can do.","It must be done in silence.","It is a family activity everyone joins in.","It takes only one person a minute."],"explanation":"原文 ''a family affair, with everyone… joining in'' 的转述。"},{"q":"What stayed with the writer the longest?","answer":"D","options":["The high price of the meal.","The name of the street.","The colour of the menu.","The warmth and friendship shown to strangers."],"explanation":"末句 ''the warmth and friendship that were offered to… strangers'' 的转述。"}]'::jsonb, '[{"word":"chef","cn":"厨师"},{"word":"peppercorn","cn":"花椒"},{"word":"vinegar","cn":"醋"},{"word":"affair","cn":"事情"}]'::jsonb, 2, 'elective2', 'U3');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'Learning to Make Dumplings', 'Last winter my grandma decided to teach me how to (1)____ dumplings. First she mixed flour and water into a soft (2)____, kneading it until it was smooth. Then she showed me how to (3)____ the green onions into tiny pieces and mix them with the meat. At first my dumplings looked ugly, and I almost wanted to give (4)____. But Grandma said that cooking, like writing, needs (5)____, so I should be patient. Little by little, my hands learned the (6)____, and the dumplings began to look much better. When they were boiled, we ate them dipped in (7)____, which made them even more delicious. Grandma told me that (8)____ dumplings together has always been a family affair in the north of China. Now, whenever I (9)____ a dumpling, I think of that warm afternoon in her kitchen. Cooking, I have learned, is also a way of passing on (10)____.', 151, 2, '[{"q":"1","answer":"A","options":["make","throw","sell","lose"],"explanation":"make dumplings 包饺子。"},{"q":"2","answer":"B","options":["price","dough","noise","ticket"],"explanation":"soft dough 软面团。"},{"q":"3","answer":"C","options":["paint","drive","slice","drop"],"explanation":"slice the onions 把葱切碎/切片。"},{"q":"4","answer":"D","options":["in","off","out","up"],"explanation":"give up 放弃。"},{"q":"5","answer":"A","options":["patience","money","anger","noise"],"explanation":"needs patience 需要耐心(与后文 be patient 呼应)。"},{"q":"6","answer":"B","options":["weather","trick","price","size"],"explanation":"learned the trick 学会了诀窍。"},{"q":"7","answer":"C","options":["sugar","oil","vinegar","water"],"explanation":"dipped in vinegar 蘸醋。"},{"q":"8","answer":"D","options":["selling","breaking","hiding","making"],"explanation":"making dumplings 包饺子(动名词作主语)。"},{"q":"9","answer":"A","options":["eat","lose","sell","drop"],"explanation":"whenever I eat 每当我吃。"},{"q":"10","answer":"B","options":["money","culture","noise","rubbish"],"explanation":"passing on culture 传承文化。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'Ordering at a Hunan Restaurant', 'When the foreign guest sat down, the waiter politely asked, "Are you ready to (1)____, sir?" The guest was not sure what to choose, so he asked the waiter to (2)____ something special. "This restaurant has the best steamed fish head (3)____ with chillies," the waiter said with a smile. The guest loved (4)____ food, so the dish sounded perfect for him. He also ordered some hand-torn (5)____ and a bowl of mushroom soup. While he waited, he watched the busy (6)____ cooking over the fire in the open kitchen. Soon the table was (7)____ with colourful dishes, and the smell of garlic filled the air. The fish was hot and spicy, with an (8)____ flavour he had never tasted before. "How would you like to (9)____?" the waiter asked at the end of the meal. "By mobile phone," the guest answered, already planning to (10)____ to this restaurant again.', 150, 2, '[{"q":"1","answer":"C","options":["sleep","leave","order","drive"],"explanation":"ready to order 准备点菜。"},{"q":"2","answer":"D","options":["forget","lose","hide","recommend"],"explanation":"recommend something 推荐点东西。"},{"q":"3","answer":"A","options":["covered","sold","thrown","left"],"explanation":"covered with chillies 盖满辣椒。"},{"q":"4","answer":"B","options":["quiet","spicy","empty","broken"],"explanation":"spicy food 辣的食物。"},{"q":"5","answer":"C","options":["money","weather","cabbage","noise"],"explanation":"hand-torn cabbage 手撕包菜。"},{"q":"6","answer":"D","options":["driver","doctor","farmer","chef"],"explanation":"the busy chef 忙碌的厨师。"},{"q":"7","answer":"A","options":["covered","sold","broken","lost"],"explanation":"the table was covered with dishes 桌上摆满了菜。"},{"q":"8","answer":"B","options":["empty","exceptional","ugly","boring"],"explanation":"an exceptional flavour 特别的风味。"},{"q":"9","answer":"C","options":["sleep","cry","pay","leave"],"explanation":"How would you like to pay? 您想怎么付款?"},{"q":"10","answer":"D","options":["sell","break","hide","return"],"explanation":"return to this restaurant 再来这家餐厅。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'Changing My Eating Habits', 'A year ago, my diet was full of junk food and sweet (1)____. I drank soda every day and rarely touched any (2)____ or vegetables. Then a doctor told me that too much sugar was bad for my (3)____, and I decided to make a change. First, I cut (4)____ on desserts and stopped buying sweet drinks. Next, I started to (5)____ more fresh food, which is full of vitamins and fibre. I also learned to eat more (6)____, chewing each bite carefully instead of rushing. My mother said that (7)____ is the key, so I tried not to eat too much or too little. Slowly, I felt more (8)____ and full of energy. Now I keep (9)____ meal times, eating three times a day at the same hours. Looking back, I am proud of the small (10)____ that changed my whole life.', 143, 2, '[{"q":"1","answer":"A","options":["drinks","stones","cars","books"],"explanation":"sweet drinks 甜饮料。"},{"q":"2","answer":"B","options":["money","fruit","noise","paper"],"explanation":"fruit or vegetables 水果或蔬菜。"},{"q":"3","answer":"C","options":["hair","shoes","health","phone"],"explanation":"bad for my health 对健康有害。"},{"q":"4","answer":"D","options":["in","off","out","down"],"explanation":"cut down on 减少。"},{"q":"5","answer":"A","options":["consume","throw","sell","break"],"explanation":"consume fresh food 吃新鲜食物。"},{"q":"6","answer":"B","options":["loudly","slowly","angrily","sadly"],"explanation":"eat slowly 慢慢吃。"},{"q":"7","answer":"C","options":["money","noise","moderation","weather"],"explanation":"moderation is the key 适度是关键。"},{"q":"8","answer":"D","options":["tired","afraid","bored","healthy"],"explanation":"felt more healthy 感觉更健康。"},{"q":"9","answer":"A","options":["consistent","broken","empty","lost"],"explanation":"consistent meal times 规律的进餐时间。"},{"q":"10","answer":"B","options":["price","change","noise","machine"],"explanation":"the small change 这个小小的改变。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'Foods from Far Away', 'Travelling around the world is a wonderful way to taste new (1)____. In Italy, Greece, and Spain, people cook with olives, figs, and other fresh (2)____ that have shaped their food for many centuries. A traditional Western dinner may (3)____ of soup, a main course, and a sweet dessert. In some countries, brave eaters even enjoy dishes that other people find quite (4)____. Recently, a few diners have begun to try insects, which are surprisingly high in (5)____ and cheaper than beef. To one person a food may seem perfectly normal, (6)____ to another the same dish feels shocking. What we think of as strange really (7)____ on where we grew up. By keeping an open (8)____, a traveller can discover that the world''s kitchens are full of (9)____. Almost every food, however unusual, makes perfect (10)____ to someone somewhere on the planet.', 143, 2, '[{"q":"1","answer":"C","options":["stones","cars","flavours","rules"],"explanation":"new flavours 新的风味。"},{"q":"2","answer":"D","options":["machines","tickets","noises","ingredients"],"explanation":"fresh ingredients 新鲜食材。"},{"q":"3","answer":"A","options":["consist","sell","break","lose"],"explanation":"consist of 由……组成。"},{"q":"4","answer":"B","options":["cheap","strange","happy","quiet"],"explanation":"find strange 觉得奇怪。"},{"q":"5","answer":"C","options":["noise","price","protein","weather"],"explanation":"high in protein 富含蛋白质。"},{"q":"6","answer":"D","options":["because","so","if","yet"],"explanation":"yet 表转折,''然而''。"},{"q":"7","answer":"A","options":["depends","sells","breaks","loses"],"explanation":"depends on 取决于。"},{"q":"8","answer":"B","options":["door","mind","shop","garden"],"explanation":"an open mind 开放的心态。"},{"q":"9","answer":"C","options":["prices","noises","surprises","mistakes"],"explanation":"full of surprises 充满惊喜。"},{"q":"10","answer":"D","options":["money","noise","trouble","sense"],"explanation":"make sense 说得通;有道理。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'The Slow-Eating Test', 'Our science teacher gave us an interesting (1)____ to try at home. We had to eat one meal as slowly as we could and write down how we (2)____. She explained that it takes about twenty minutes for your brain to tell your body that you are (3)____. People who (4)____ too quickly often eat far more than they need. That evening, I sat down and ate my rice very (5)____, putting down my chopsticks between bites. To my surprise, I felt full after only a (6)____ amount of food. Eating slowly also let me really (7)____ each flavour, something I had never noticed before. The next day in class, almost everyone (8)____ the same result. Our teacher smiled and said that there is no magic (9)____ to healthy eating, only good habits built day by day. Since then, I have tried hard to keep (10)____ meal times and to enjoy every bite.', 153, 2, '[{"q":"1","answer":"A","options":["test","stone","car","rule"],"explanation":"an interesting test 一个有趣的实验。"},{"q":"2","answer":"B","options":["paid","felt","sold","drove"],"explanation":"how we felt 我们的感受。"},{"q":"3","answer":"C","options":["empty","angry","full","late"],"explanation":"you are full 你饱了。"},{"q":"4","answer":"D","options":["sleep","leave","cry","chew"],"explanation":"chew too quickly 嚼得太快。"},{"q":"5","answer":"A","options":["slowly","loudly","angrily","sadly"],"explanation":"ate very slowly 吃得很慢。"},{"q":"6","answer":"B","options":["loud","modest","broken","empty"],"explanation":"a modest amount 适量。"},{"q":"7","answer":"C","options":["sell","lose","enjoy","break"],"explanation":"enjoy each flavour 享受每一种味道。"},{"q":"8","answer":"D","options":["sold","broke","lost","reported"],"explanation":"reported the same result 报告了同样的结果。"},{"q":"9","answer":"A","options":["trick","price","noise","stone"],"explanation":"no magic trick 没有神奇诀窍。"},{"q":"10","answer":"B","options":["broken","consistent","empty","lost"],"explanation":"consistent meal times 规律的进餐时间。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (11, 'elective2', 'U3', 'Designing Our Own Restaurant', 'For our class project, my group had to (1)____ a new restaurant for our city. First we decided what kind of (2)____ we would serve, and we chose light, fresh Cantonese dishes. Next we made a (3)____ in both Chinese and English, so foreign guests could read it easily. We wanted every dish to use fresh (4)____ rather than processed food. One member, who loved cooking, agreed to act as the (5)____ in charge of the kitchen. Another designed the dining (6)____ with soft lights and quiet music. We kept our prices low, so that the meals would not cost too (7)____. We also added a few (8)____ choices, like tofu and bean dishes, for guests who eat no meat. When we (9)____ our plan to the class, everyone seemed to like our friendly little restaurant. Our teacher said the most important thing was that we had worked together as a (10)____.', 152, 2, '[{"q":"1","answer":"C","options":["throw","sell","design","lose"],"explanation":"design a restaurant 设计一家餐厅。"},{"q":"2","answer":"D","options":["money","noise","weather","cuisine"],"explanation":"what kind of cuisine 什么风味的菜。"},{"q":"3","answer":"A","options":["menu","stone","river","wheel"],"explanation":"made a menu 做了一份菜单。"},{"q":"4","answer":"B","options":["stones","ingredients","cars","papers"],"explanation":"fresh ingredients 新鲜食材。"},{"q":"5","answer":"C","options":["driver","doctor","chef","pilot"],"explanation":"the chef 厨师。"},{"q":"6","answer":"D","options":["machine","ticket","noise","area"],"explanation":"the dining area 用餐区。"},{"q":"7","answer":"A","options":["much","loud","angry","empty"],"explanation":"cost too much 花费太多。"},{"q":"8","answer":"B","options":["broken","vegetarian","empty","noisy"],"explanation":"vegetarian choices 素食选择。"},{"q":"9","answer":"C","options":["sold","lost","presented","broke"],"explanation":"presented our plan 展示我们的方案。"},{"q":"10","answer":"D","options":["price","noise","machine","team"],"explanation":"worked together as a team 作为一个团队合作。"}]'::jsonb, 6);
