INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Introduce a Chinese Dish and Its Culture(介绍一道中国菜及其文化)', 'Introduce a Chinese Dish and Its Culture(介绍一道中国菜及其文化)', '假设你叫李华,一位外国朋友想了解中国的饮食文化。请用英语写一篇约100词的说明文,介绍一道你喜欢的中国菜,内容包括:① 这道菜的名称、主要食材和大致做法;② 它的味道或特色;③ 这道菜背后体现的中国饮食文化(如家人团聚、待客之道、地方特色等)。注意:用词地道、围绕中心、条理清楚。', 'Suppose you are Li Hua. A foreign friend wants to learn about Chinese food culture. Write a passage of about 100 words to introduce a Chinese dish you like, including: 1) its name, main ingredients, and how it is made; 2) its taste or special feature; 3) the Chinese food culture behind it (e.g. family reunion, welcoming guests, or local character).', '["介绍菜名与食材(One of my favourite dishes is … It is made with …)","说明做法与味道(It is cooked by … and tastes …)","点出背后的文化(More than a dish, it shows … / It brings the family together.)","用词地道、围绕中心、条理清楚"]'::jsonb, 70, 100, 'One of my favourite Chinese dishes is boiled dumplings. They are made by wrapping a filling of minced pork and sliced green onions inside a thin piece of dough, and then boiling them in hot water. We usually eat them dipped in vinegar, which gives them a fresh, slightly sour taste. To me, however, dumplings are more than just food. In the north of China, making dumplings has always been a family affair, with everyone from the youngest child to the oldest grandparent joining in. Through this simple dish, you can really feel the warmth, the friendship, and the love of family that lie at the heart of Chinese food culture.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["One of my favourite Chinese dishes is boiled dumplings.","They are made by wrapping minced pork and green onions inside a thin piece of dough.","We usually eat them dipped in vinegar, which gives them a fresh, slightly sour taste.","Through this simple dish, you can feel the warmth and love that lie at the heart of Chinese food culture."]'::jsonb, '[{"wrong":"Cooking dumplings are fun.","correct":"Cooking dumplings is fun.","note":"动名词作主语,谓语用单数 is。"},{"wrong":"The dish is made by boil it in water.","correct":"The dish is made by boiling it in water.","note":"介词 by 后接动名词 boiling。"},{"wrong":"We eat them with dip in vinegar.","correct":"We eat them dipped in vinegar.","note":"过去分词 dipped 作状语,表被动/状态。"}]'::jsonb, '【介绍一道中国菜结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective2', 'U3', '{"title":"-ing 形式复习·动名词与现在分词 速查","intro":"-ing 形式有两副面孔:动名词(像名词,作主语/宾语/表语)和现在分词(像形容词/副词,作定语/状语/补足语)。判断口诀:能换成 ''the act of doing'' 多是动名词;描述''正在/主动''修饰名词或句子多是现在分词。","table":{"headers":["用法","在句中作什么 / 例句"],"rows":[["动名词作主语","Cooking is an art.(谓语用单数 is)"],["动名词作宾语","I enjoy tasting new dishes. / good at cooking(介词后)"],["动名词作表语","Her hobby is baking."],["现在分词作定语","the boiling water(= 正在沸腾的水,主动/进行)"],["现在分词作状语","Tasting the dish, he nodded.(伴随/时间/原因)"],["-ing 作宾补","I saw him cooking. / keep sb waiting(正在进行)"]]},"specialRules":[{"rule":"动名词作主语,谓语动词用单数","mark":"Eating slowly helps you.(helps 而非 help)"},{"rule":"现在分词(doing)表主动/进行,过去分词(done)表被动/完成","mark":"the boiling water(水自己在沸) vs the dish covered with chillies(菜被覆盖)"},{"rule":"感官动词 see/hear/watch/feel/find + sb + doing 表''正在做''","mark":"I saw him cooking."},{"rule":"remember/forget/stop/try + to do(将要做) vs + doing(做过/正做)含义不同","mark":"stop to rest(停下去休息) / stop adding salt(不再加盐)"}],"why":["动名词把动作''名词化'',所以能占主语、宾语、表语的位置;现在分词把动作变成''修饰语'',所以能像形容词修饰名词、像副词修饰整句——同一个 -ing,角色不同,功能就不同。"],"gaokaoPoints":["现在分词 vs 过去分词作定语/状语:看修饰对象是''主动/进行''还是''被动/完成''(boiling water √ / boiled eggs √)。","感官动词 + sb + doing 与 remember/stop/try 后 to do 与 doing 的意义区别,是语法填空与单选高频考点。"],"examVsReal":[{"exam":"Tasting the soup, he smiled.（考试/书面)","real":"He tasted the soup and smiled.","note":"考试爱用现在分词作状语;口语里常直接用两个并列动词"},{"exam":"I saw him cooking.（强调正在进行)","real":"I saw him cook the whole meal.（强调看完全过程)","note":"doing 看到一部分/正在进行;do 看到从头到尾,两者都对,意义略不同"}]}'::jsonb);
